// Lead Enrichment via APIs
const items = $input.all();
const enriched = [];

for (const item of items) {
  const email = item.json.email;
  let enrichmentData = {};

  try {
    // Simular chamada API Clearbit (substituir por API real)
    // const companyData = await $helpers.httpRequest({
    //   url: `https://company.clearbit.com/v2/companies/find?email=${email}`,
    //   headers: {'Authorization': `Bearer ${$env.CLEARBIT_API_KEY}`}
    // });

    // Dados enriquecidos (exemplo)
    enrichmentData = {
      company_name: item.json.company || 'N/A',
      company_domain: email.split('@')[1] || '',
      company_size: Math.floor(Math.random() * 500) + 10,
      company_industry: ['Technology', 'Finance', 'Healthcare', 'Retail'][Math.floor(Math.random() * 4)],
      company_location: ['São Paulo', 'Rio de Janeiro', 'Belo Horizonte'][Math.floor(Math.random() * 3)],
      enriched: true,
      enriched_at: new Date().toISOString()
    };
  } catch (error) {
    enrichmentData = {
      enriched: false,
      enrichment_error: error.message
    };
  }

  enriched.push({
    json: {
      ...item.json,
      ...enrichmentData
    }
  });
}

return enriched;

